<?php
$uid = (int)$u['id']; $ref = preg_replace('/[^a-f0-9]/', '', (string)($_GET['ref'] ?? '')); $s = row('SELECT s.*, m.business_name, m.user_id mu FROM checkout_sessions s JOIN merchants m ON m.id=s.merchant_id WHERE s.ref=?', [$ref]);
if (!$s) { http_response_code(404); echo page_head('Checkout') . card('', empty_state('This checkout link is not valid.')); return; }
handle('co_pay', function () use ($uid, $ref) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); $r = Pay::payCheckout($uid, $ref, idem_key()); if ($r['status'] === 'approval_pending') { flash('warn', 'This payment needs approval from your designated approvers.'); redirect(url('family')); } flash('ok', 'Payment successful.'); redirect(url('receipt', ['ref' => $r['ref']])); });
$live = $s['status'] === 'open' && strtotime($s['expires_at']) > time(); $st = $s['status'] === 'open' && !$live ? 'expired' : $s['status'];
echo page_head('Merchant checkout', 'Simulated QR checkout. Review the details, then confirm with your PIN.') . '<div class="grid g2">' . card($s['business_name'], '<dl class="kv"><dt>Amount</dt><dd>' . mny($s['amount']) . '</dd><dt>Fee</dt><dd>Paid by the merchant</dd><dt>Note</dt><dd style="font-weight:400">' . e($s['note'] ?: '-') . '</dd><dt>Status</dt><dd>' . badge($st) . '</dd><dt>Expires</dt><dd>' . e(fdate($s['expires_at'])) . '</dd></dl><div class="total-row"><span>You pay</span><span>' . mny($s['amount']) . '</span></div><p class="hint">Balance after payment: ' . mbal(dec(cents(Ledger::wallet($uid, 'BDT')['balance']) - cents($s['amount']))) . '. Payments are final; you can open a dispute from the receipt.</p>') .
  card('Confirm', $live && (int)$s['mu'] !== $uid ? form_start('co_pay') . pin_field() . btn('Pay ' . money($s['amount'])) . '</form>' : '<p class="muted">' . ((int)$s['mu'] === $uid ? 'This is your own checkout.' : 'This checkout can no longer be paid.') . '</p>') . '</div>';
